<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
import AppModal from '../components/AppModal.vue'
import AppIcon from '../components/AppIcon.vue'
import {dateTime} from '../uiHelpers'
import {state,request,refresh,notify} from '../store'
const tab=ref('devices'),checking=ref(''),deviceDetails=ref(''),appDetails=ref('')
function observe(id:string){deviceId.value=id;observeOpen.value=true}
function ownerLink(owner:string){return state.runs.some(r=>r.id===owner)?'/runs/'+owner:state.tasks.some(t=>t.id===owner)?'/agent/'+owner:''}
const deviceOpen=ref(false),appOpen=ref(false),observeOpen=ref(false),busy=ref(false)
const device=ref({name:'',udid:'emulator-5554',appium_url:'http://appium:4723',node_url:'http://appium:4724',device_id:''})
const application=ref({name:'',package:'',activity:'',version:'',file:null as File|null})
const deviceId=ref(''),appId=ref(''),session=ref(''),source=ref(''),image=ref(''),by=ref('accessibility id'),selector=ref(''),text=ref('')
async function saveDevice(){try{await request('/devices',device.value);await refresh(true);deviceOpen.value=false;notify('设备配置已保存')}catch(e){notify(String(e))}}
async function check(id:string){checking.value=id;try{await request('/devices/'+id+'/check',{});await refresh(true)}catch(e){notify(String(e))}finally{checking.value=''}}
function fileSelected(e:Event){application.value.file=(e.target as HTMLInputElement).files?.[0]??null}
async function saveApp(){busy.value=true;try{if(application.value.file){const params=new URLSearchParams({name:application.value.name,package:application.value.package,activity:application.value.activity,version:application.value.version});const response=await fetch('/api/applications/upload?'+params,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:application.value.file});const value=await response.json();if(!response.ok)throw new Error(value.message??value.detail)}else await request('/applications',{...application.value,version:application.value.version||'installed'});await refresh(true);appOpen.value=false;notify('应用版本已保存')}catch(e){notify(String(e))}finally{busy.value=false}}
async function action(action:string){busy.value=true;try{const value=await request('/tools/mobile_action',{arguments:{action,session_id:session.value,device_id:deviceId.value,app_id:appId.value,by:by.value,selector:selector.value,text:text.value}});if(value.session_id)session.value=value.session_id;if(value.image){image.value='data:image/png;base64,'+value.image;source.value=value.source}if(action==='open')await actionObserve();await refresh(true)}catch(e){const message=String(e);notify(message);if(message.includes('超时')||message.includes('已关闭')){session.value='';source.value='';image.value=''}}finally{busy.value=false}}
async function actionObserve(){const value=await request('/tools/mobile_action',{arguments:{action:'observe',session_id:session.value}});image.value='data:image/png;base64,'+value.image;source.value=value.source}
async function close(){if(busy.value)return notify('等待当前设备操作完成');if(session.value){try{await request('/tools/mobile_action',{arguments:{action:'close',session_id:session.value}})}catch(e){notify(String(e))}}session.value='';observeOpen.value=false;await refresh(true)}
let heartbeat:ReturnType<typeof setInterval>|undefined
onMounted(()=>{heartbeat=setInterval(()=>{if(observeOpen.value&&session.value&&!busy.value&&document.visibilityState==='visible')void action('observe')},30000)})
onBeforeUnmount(()=>{if(heartbeat)clearInterval(heartbeat);if(session.value)void close()})
</script>
<template><div class="page"><div class="page-heading"><div><h1>应用与设备</h1><p>管理 Android 设备与应用版本，连接后即可观察和测试。</p></div><div class="heading-actions"><button class="button secondary" @click="deviceOpen=true">添加设备</button><button class="button primary" @click="appOpen=true">添加应用版本</button></div></div>
<div class="local-tabs" role="tablist" aria-label="设备与应用分类"><button role="tab" :aria-selected="tab==='devices'" :class="{active:tab==='devices'}" @click="tab='devices'">测试设备 <span>{{state.devices.length}}</span></button><button role="tab" :aria-selected="tab==='apps'" :class="{active:tab==='apps'}" @click="tab='apps'">应用版本 <span>{{state.applications.length}}</span></button></div>
<section v-if="tab==='devices'" class="panel table-panel"><table class="data-table"><thead><tr><th>设备</th><th>状态／最近检查</th><th>占用情况</th><th>操作</th></tr></thead><tbody><template v-for="d in state.devices" :key="d.id"><tr><td><strong>{{d.name}}</strong><div class="table-secondary">Android {{d.androidVersion??'待识别'}}</div></td><td><span class="device-state" :class="d.status"><i/>{{d.status==='online'?'在线':d.status==='offline'?'离线':'待检查'}}</span><div class="table-secondary">{{d.lastCheck?dateTime(d.lastCheck):'尚未检查'}}</div></td><td><RouterLink v-if="d.busy&&ownerLink(d.owner)" :to="ownerLink(d.owner)" class="text-button">查看占用任务</RouterLink><span v-else>{{d.busy?'使用中':'空闲'}}</span></td><td><div class="row-actions"><button class="text-button" :disabled="d.busy" @click="observe(d.id)">观察设备</button><button class="text-button" :disabled="!!checking" @click="check(d.id)">{{checking===d.id?'检查中…':'检查连接'}}</button><button class="text-button" @click="deviceDetails=deviceDetails===d.id?'':d.id">详情</button></div></td></tr><tr v-if="deviceDetails===d.id"><td colspan="4"><div class="device-details"><p>设备标识：<code>{{d.udid}}</code></p><p>Appium：<code>{{d.appiumUrl}}</code></p><p>{{d.message||'设备状态尚未检查'}}<span v-if="d.busy"> · 占用：{{d.owner}}</span></p><button class="button secondary" :disabled="d.busy" @click="device={name:d.name,udid:d.udid,appium_url:d.appiumUrl,node_url:d.nodeUrl,device_id:d.id};deviceOpen=true">编辑连接</button></div></td></tr></template></tbody></table><div v-if="!state.devices.length" class="empty-state"><h3>添加一台测试设备</h3><p>启动 Android 执行节点后配置连接。</p><button class="button secondary" @click="deviceOpen=true">添加设备</button></div></section>
<section v-else class="panel table-panel"><div class="panel-heading"><h2>应用版本</h2><RouterLink to="/cases" class="text-button">编写 APP 用例</RouterLink></div><table class="data-table"><thead><tr><th>应用</th><th>版本</th><th>包名</th><th>操作</th></tr></thead><tbody><template v-for="a in state.applications" :key="a.id"><tr><td><strong>{{a.name}}</strong><div class="table-secondary">{{a.path?'APK 文件':'设备已有应用'}}</div></td><td>{{a.version}}</td><td>{{a.package||'由 APK 自动识别'}}</td><td><button class="text-button" @click="appDetails=appDetails===a.id?'':a.id">详情</button></td></tr><tr v-if="appDetails===a.id"><td colspan="4"><div class="device-details"><p class="mono">{{a.id}}</p><p>启动 Activity：{{a.activity||'自动识别'}}</p><p class="mono">SHA256：{{a.hash}}</p></div></td></tr></template></tbody></table><div v-if="!state.applications.length" class="empty-state"><h3>添加应用版本</h3><p>上传 APK，或登记设备上已有的应用。</p><button class="button secondary" @click="appOpen=true">添加应用版本</button></div></section>
<AppModal :open="deviceOpen" title="Android 设备连接" @close="deviceOpen=false"><form @submit.prevent="saveDevice"><div class="modal-body form-grid"><label class="field-label">设备名称<input v-model="device.name" required/></label><label class="field-label">ADB 设备标识（udid）<input v-model="device.udid" required/></label><label class="field-label">Appium 执行地址<input v-model="device.appium_url" type="url" required/></label><label class="field-label">设备节点地址（可选）<input v-model="device.node_url" type="url"/></label><p class="form-hint">本地 Compose：Appium http://appium:4723，节点 http://appium:4724。地址必须能被本地执行器和测试容器访问。</p></div><div class="modal-actions"><button class="button primary" type="submit">保存设备</button></div></form></AppModal>
<AppModal :open="appOpen" title="添加应用版本" @close="appOpen=false"><form @submit.prevent="saveApp"><div class="modal-body form-grid"><label class="field-label">应用名称<input v-model="application.name" required/></label><label class="field-label">APK 文件（可选，最大 100MB）<input type="file" accept=".apk" @change="fileSelected"/></label><label class="field-label">包名<input v-model="application.package" :required="!application.file" placeholder="io.appium.android.apis"/></label><label class="field-label">启动 Activity（可选）<input v-model="application.activity" placeholder=".ApiDemos"/></label><label class="field-label">版本说明<input v-model="application.version" placeholder="留空使用 APK 哈希"/></label><p class="form-hint">上传新文件创建独立应用版本。未上传文件时登记设备已有应用；包名必填。</p></div><div class="modal-actions"><button class="button primary" :disabled="busy" type="submit">{{busy?'保存中…':'保存应用版本'}}</button></div></form></AppModal>
<AppModal class="device-modal" :open="observeOpen" title="观察 Android 设备" @close="close"><div class="modal-body"><div v-if="!session" class="form-grid"><label class="field-label">设备<select v-model="deviceId" class="select"><option value="">选择设备</option><option v-for="d in state.devices" :key="d.id" :value="d.id" :disabled="d.busy">{{d.name}} {{d.busy?'占用中':''}}</option></select></label><label class="field-label">应用版本<select v-model="appId" class="select"><option value="">选择应用</option><option v-for="a in state.applications" :key="a.id" :value="a.id">{{a.name}} · {{a.version}}</option></select></label><button class="button primary" :disabled="!deviceId||!appId||busy" @click="action('open')">{{busy?'正在启动…':'打开应用并观察'}}</button></div><template v-else><div class="device-observation"><figure class="device-screen"><img v-if="image" :src="image" alt="Android 设备实时截图"/><figcaption>{{state.devices.find(d=>d.id===deviceId)?.name}}</figcaption></figure><div class="form-grid"><label class="field-label">定位方式<select v-model="by" class="select"><option>accessibility id</option><option>id</option><option>xpath</option><option>-android uiautomator</option></select></label><label class="field-label">定位表达式<input v-model="selector"/></label><label class="field-label">输入文本<input v-model="text"/></label><div class="heading-actions"><button class="button secondary" :disabled="busy||!selector" @click="action('click')">点击</button><button class="button secondary" :disabled="busy||!selector" @click="action('input')">输入</button><button class="button secondary" :disabled="busy" @click="action('back')">返回</button><button class="button secondary" :disabled="busy" @click="action('observe')">刷新截图</button></div><details><summary>页面元素 XML</summary><pre class="log-block">{{source}}</pre></details></div></div></template></div><div class="modal-actions"><button class="button secondary" :disabled="busy" @click="close">关闭并释放设备</button></div></AppModal>
</div></template>
